// Writes src/parts-catalog.js from docs/parts-catalog.json and src/engines-data.js from docs/engines.json,
// so the browser and Node can import them.
// Run after editing the catalog: node tools/build-parts.mjs
import { readFileSync, writeFileSync } from 'node:fs';
const root = new URL('../../', import.meta.url);
const data = JSON.parse(readFileSync(new URL('docs/parts-catalog.json', root), 'utf8'));
writeFileSync(new URL('web/src/parts-catalog.js', root),
  '// Generated by tools/build-parts.mjs from docs/parts-catalog.json. Edit the JSON, not this file.\n' +
  `export const CATALOG = ${JSON.stringify(data, null, 1)};\n`);
console.log(`pistons ${data.pistons.length}, rods ${data.rods.length}, cranks ${data.cranks.length}`);
const engines = JSON.parse(readFileSync(new URL('docs/engines.json', root), 'utf8'));
writeFileSync(new URL('web/src/engines-data.js', root),
  '// Generated by tools/build-parts.mjs from docs/engines.json (built by tools/build-engines.py). Edit those, not this file.\n' +
  `export const ENGINES = ${JSON.stringify(engines, null, 1)};\n`);
console.log(`blocks ${engines.blocks.length}, heads ${engines.heads.length}, oil pumps ${engines.oilPumps.length}`);
